#!/usr/bin/env python3
"""Require an app version bump for non-documentation changes."""
import argparse
import os
from pathlib import Path, PurePosixPath
import re
import subprocess
import sys
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parent.parent
ANDROID = '{http://schemas.android.com/apk/res/android}'
VERSION = re.compile(r'(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)')


def git(*args):
    return subprocess.check_output(['git', *args], cwd=ROOT).decode('utf-8')


def documentation(path):
    file = PurePosixPath(path)
    # index.json is generated by both release workflows; it must not release again.
    return (path == 'scenes/index.json' or path in {'LICENSE', 'NOTICE'}
            or file.parts[:2] == ('.github', 'ISSUE_TEMPLATE')
            or file.parts[0] in {'docs', 'screenshots'}
            or file.suffix.lower() in {'.md', '.rst', '.adoc'})


def manifest(ref):
    root = ET.fromstring(git('show', ref + ':AndroidManifest.xml'))
    name = root.attrib[ANDROID + 'versionName']
    match = VERSION.fullmatch(name)
    if not match:
        raise ValueError('versionName must be a stable semantic version, for example 4.5.1')
    code = int(root.attrib[ANDROID + 'versionCode'])
    if not 0 < code <= 2100000000:
        raise ValueError('versionCode must be between 1 and 2100000000')
    return name, tuple(map(int, match.groups())), code


def check(base, head, pull_request=False, tag=None):
    # Resolve refs once so diffs, metadata and tag checks use the same commits.
    head = git('rev-parse', '--verify', head + '^{commit}').strip()
    if not tag:
        if not base:
            raise ValueError('--base is required when checking changes')
        if set(base) == {'0'}:
            base = git('hash-object', '-t', 'tree', '/dev/null').strip()
            previous = None  # Initial push of a repository.
        else:
            base = git('rev-parse', '--verify', base + '^{commit}').strip()
            previous = manifest(base)
        diff_base = git('merge-base', base, head).strip() if pull_request else base
        paths = git('diff', '--no-renames', '--name-only', '-z', diff_base, head).split('\0')
        changed = [path for path in paths if path and not documentation(path)]
        if not changed:
            print('Documentation/generated catalogue only: no version bump or APK release needed.')
            return {'release_needed': 'false'}
        print('Release changes:\n' + '\n'.join('  ' + path for path in changed))

    name, version, code = manifest(head)
    expected_tag = 'v' + name
    if tag:
        if tag != expected_tag:
            raise ValueError('Release tag must match versionName: ' + expected_tag)
    elif previous:
        if version <= previous[1] or code <= previous[2]:
            raise ValueError('Code changes require BOTH a higher versionName and versionCode '
                             f'in AndroidManifest.xml (base: {previous[0]}, code {previous[2]}; '
                             f'current: {name}, code {code}).')

    changelog = git('show', head + ':CHANGELOG.md')
    entry = re.search(r'^## ' + re.escape(name) + r'\r?\n(.*?)(?=^## |\Z)',
                      changelog, re.M | re.S)
    if not entry or not entry.group(1).strip():
        raise ValueError('Add a non-empty CHANGELOG.md entry headed "## ' + name + '".')

    existing = subprocess.run(['git', 'rev-parse', '--verify', '--quiet',
                               'refs/tags/' + expected_tag + '^{commit}'],
                              cwd=ROOT, capture_output=True, text=True)
    if existing.returncode == 0 and existing.stdout.strip() != head:
        raise ValueError(expected_tag + ' already belongs to another commit; choose a new version.')
    print(f'Validated {expected_tag} (Android versionCode {code}) at {head}')
    return {'release_needed': 'true', 'tag': expected_tag, 'sha': head}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--base')
    parser.add_argument('--head', default='HEAD')
    parser.add_argument('--pull-request', action='store_true')
    parser.add_argument('--tag', help='Validate an explicit tag/manual release instead of a diff')
    args = parser.parse_args()
    try:
        outputs = check(args.base, args.head, args.pull_request, args.tag)
    except (ValueError, KeyError, ET.ParseError, subprocess.CalledProcessError) as error:
        print('Version check failed: ' + str(error), file=sys.stderr)
        return 1
    if os.environ.get('GITHUB_OUTPUT'):
        with open(os.environ['GITHUB_OUTPUT'], 'a') as output:
            for key, value in outputs.items():
                output.write(key + '=' + value + '\n')
    return 0


if __name__ == '__main__':
    sys.exit(main())
